import type { LearnerStateEvent } from '../domain/state-events';
import type { LearnerStateStore } from './learner-state-store';

export class InMemoryLearnerStateStore implements LearnerStateStore {
  private snapshots = new Map<LearnerId, LearnerStateSnapshot>();
  private events = new Map<LearnerId, LearnerStateEvent[]>();

  async get(learnerId: LearnerId): Promise<LearnerStateSnapshot | null> {
    return this.snapshots.get(learnerId) ?? null;
  }

  async save(snapshot: LearnerStateSnapshot): Promise<void> {
    this.snapshots.set(snapshot.profile.identity.learnerId, snapshot);
  }

  async appendEvent(event: LearnerStateEvent): Promise<void> {
    const existing = this.events.get(event.learnerId) ?? [];
    existing.push(event);
    this.events.set(event.learnerId, existing);
  }

  async listEvents(learnerId: LearnerId): Promise<LearnerStateEvent[]> {
    return [...(this.events.get(learnerId) ?? [])];
  }
}
