import type { LearnerId, LearnerMemoryItem, LearnerStateSnapshot, SkillLevel } from '../domain/learner';
import type { LearnerStateEvent } from '../domain/state-events';
import type { LearnerStateStore } from './learner-state-store';

export class LearnerStateService {
  constructor(private readonly store: LearnerStateStore) {}

  async ensureLearner(learnerId: LearnerId, now = new Date().toISOString()): Promise<LearnerStateSnapshot> {
    const existing = await this.store.get(learnerId);
    if (existing) return existing;

    const snapshot: LearnerStateSnapshot = {
      profile: createEmptyLearnerProfile(learnerId, now),
      lastActivityAt: now,
    };

    await this.store.save(snapshot);
    await this.store.appendEvent(this.event(learnerId, 'learner.created', now, { learnerId }));
    return snapshot;
  }

  async updateSkillLevel(learnerId: LearnerId, skillLevel: SkillLevel, now = new Date().toISOString()) {
    const snapshot = await this.ensureLearner(learnerId, now);
    snapshot.profile.skillLevel = skillLevel;
    snapshot.profile.identity.updatedAt = now;
    snapshot.profile.version += 1;
    snapshot.lastActivityAt = now;
    await this.store.save(snapshot);
    await this.store.appendEvent(this.event(learnerId, 'learner.profile.updated', now, { skillLevel }));
    return snapshot;
  }

  async upsertMemory(learnerId: LearnerId, item: Omit<LearnerMemoryItem, 'updatedAt'>, now = new Date().toISOString()) {
    const snapshot = await this.ensureLearner(learnerId, now);
    const memoryItem: LearnerMemoryItem = { ...item, updatedAt: now };
    const idx = snapshot.profile.memory.findIndex((m) => m.key === item.key);
    if (idx >= 0) snapshot.profile.memory[idx] = memoryItem;
    else snapshot.profile.memory.push(memoryItem);
    snapshot.profile.identity.updatedAt = now;
    snapshot.profile.version += 1;
    snapshot.lastActivityAt = now;
    await this.store.save(snapshot);
    await this.store.appendEvent(this.event(learnerId, 'learner.memory.upserted', now, { key: item.key }));
    return snapshot;
  }

  async recordAssessment(learnerId: LearnerId, payload: Record<string, unknown>, now = new Date().toISOString()) {
    const snapshot = await this.ensureLearner(learnerId, now);
    snapshot.lastAssessmentAt = now;
    snapshot.lastActivityAt = now;
    snapshot.profile.identity.updatedAt = now;
    snapshot.profile.version += 1;
    await this.store.save(snapshot);
    await this.store.appendEvent(this.event(learnerId, 'learner.assessment.recorded', now, payload));
    return snapshot;
  }

  private event(learnerId: LearnerId, type: LearnerStateEvent['type'], timestamp: string, payload: Record<string, unknown>): LearnerStateEvent {
    return {
      eventId: `${learnerId}-${type}-${timestamp}`,
      learnerId,
      type,
      timestamp,
      payload,
    };
  }
}
