const masteryEngine = {
  diagnose(input = {}) {
    const score = Math.max(0, Math.min(100, Number(input.score ?? 35)));
    if (score < 35) return { level: 'beginner', nextBestAction: 'Start with a guided onboarding path and one small practice lab.' };
    if (score < 70) return { level: 'intermediate', nextBestAction: 'Move to targeted practice with feedback loops.' };
    return { level: 'advanced', nextBestAction: 'Use evaluation-first challenges and deeper mastery checks.' };
  },
  evaluate(attempt = {}) {
    const correct = Boolean(attempt.correct);
    return {
      passed: correct,
      feedback: correct ? 'Great work — you demonstrated the core concept.' : 'Not yet — try the guided hint and repeat the lab.'
    };
  }
};

