const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (url.pathname === '/') {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(htmlPage());
    return;
  }

  if (url.pathname === '/api/diagnose') {
    const score = Number(url.searchParams.get('score') ?? 35);
    const result = masteryEngine.diagnose({ score });
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify(result));
    return;
  }

  if (url.pathname === '/api/evaluate') {
    const correct = url.searchParams.get('correct') === 'true';
    const result = masteryEngine.evaluate({ correct });
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify(result));
    return;
  }

  if (url.pathname === '/onboarding') {
    res.writeHead(200, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Guided onboarding: diagnose -> practice lab -> evaluation -> next best action.');
    return;
  }

  const assetPath = join(root, url.pathname);
  if (existsSync(assetPath)) {
    res.writeHead(200);
    res.end(readFileSync(assetPath));
    return;
  }

  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Not found');
});

