      "content": "import { LearnerStateRecord, LearnerStateStore, LearnerStateKey } from './learner-state-store';

export class InMemoryLearnerStateStore implements LearnerStateStore {
  private readonly store = new Map<string, Map<LearnerStateKey, LearnerStateRecord>>();

  async get<T = unknown>(learnerId: string, key: LearnerStateKey): Promise<LearnerStateRecord<T> | null> {
    const learnerBucket = this.store.get(learnerId);
    if (!learnerBucket) return null;

    const record = learnerBucket.get(key);
    return record ? ({ ...record } as LearnerStateRecord<T>) : null;
  }

  async set<T = unknown>(learnerId: string, key: LearnerStateKey, value: T): Promise<LearnerStateRecord<T>> {
    const updatedAt = new Date().toISOString();
    const record: LearnerStateRecord<T> = { key, value, updatedAt };

    let learnerBucket = this.store.get(learnerId);
    if (!learnerBucket) {
      learnerBucket = new Map();
      this.store.set(learnerId, learnerBucket);
    }

    learnerBucket.set(key, record as LearnerStateRecord);
    return { ...record };
  }

  async delete(learnerId: string, key: LearnerStateKey): Promise<boolean> {
    const learnerBucket = this.store.get(learnerId);
    if (!learnerBucket) return false;

    const deleted = learnerBucket.delete(key);
    if (learnerBucket.size === 0) {
      this.store.delete(learnerId);
    }
    return deleted;
  }

  async list(learnerId: string): Promise<Array<LearnerStateRecord>> {
    const learnerBucket = this.store.get(learnerId);
    if (!learnerBucket) return [];

    return Array.from(learnerBucket.values()).map((record) => ({ ...record }));
  }
}
