      "content": "import { LearnerStateRecord, LearnerStateStore } from './learner-state-store';

export interface LearnerIdentityState {
  learnerId: string;
  segment?: 'beginner' | 'advanced' | 'expert' | string;
  persona?: string;
}

export interface LearnerMemorySnapshot {
  identity: LearnerIdentityState;
  preferences: Record<string, unknown>;
  mastery: Record<string, unknown>;
  events: Array<{ type: string; at: string; payload?: unknown }>;
  updatedAt: string | null;
}

export class LearnerStateService {
  constructor(private readonly store: LearnerStateStore) {}

  async getState<T = unknown>(learnerId: string, key: string): Promise<T | null> {
    const record = await this.store.get<T>(learnerId, key);
    return record?.value ?? null;
  }

  async setState<T = unknown>(learnerId: string, key: string, value: T): Promise<LearnerStateRecord<T>> {
    return this.store.set(learnerId, key, value);
  }

  async removeState(learnerId: string, key: string): Promise<boolean> {
    return this.store.delete(learnerId, key);
  }

  async listState(learnerId: string): Promise<LearnerStateRecord[]> {
    return this.store.list(learnerId);
  }

  async getSnapshot(learnerId: string): Promise<LearnerMemorySnapshot> {
    const all = await this.store.list(learnerId);

    const identity = this.pickObject(all, 'identity') as LearnerIdentityState | null;
    const preferences = this.pickObject(all, 'preferences') ?? {};
    const mastery = this.pickObject(all, 'mastery') ?? {};
    const events = this.pickArray(all, 'events') ?? [];

    const updatedAt = all.reduce<string | null>((latest, record) => {
      if (!latest) return record.updatedAt;
      return record.updatedAt > latest ? record.updatedAt : latest;
    }, null);

    return {
      identity: identity ?? { learnerId },
      preferences,
      mastery,
      events,
      updatedAt,
    };
  }

  private pickObject(records: LearnerStateRecord[], key: string): Record<string, unknown> | null {
    const record = records.find((item) => item.key === key);
    if (!record || record.value === null || typeof record.value !== 'object' || Array.isArray(record.value)) {
      return null;
    }
    return record.value as Record<string, unknown>;
  }

  private pickArray(records: LearnerStateRecord[], key: string): Array<{ type: string; at: string; payload?: unknown }> | null {
    const record = records.find((item) => item.key === key);
    if (!record || !Array.isArray(record.value)) return null;
    return record.value as Array<{ type: string; at: string; payload?: unknown }>;
  }
}
